#include <cstring>
#include <gtest/gtest.h>
#include <teel_error/error.h>

TEST(Error, RepackSelf) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");

	teel_set_error("foo");
	teel_set_error("bar: %s", teel_get_error());
	teel_set_error_prefix("baz: %s", teel_get_error());

	// ideally this does not break with overlapping memory regions

	EXPECT_STREQ(teel_get_error(), "baz: bar: foo: bar: foo");
}

TEST(Error, PrefixWithoutBase) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");

	teel_set_error_prefix("failed to do xyz");

	// TODO: is it bad that we have the ": " here without anything after it?
	EXPECT_STREQ(teel_get_error(), "failed to do xyz: ");
}

TEST(Error, MultiPrefix) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");

	teel_set_error("base");
	teel_set_error_prefix("context1");
	teel_set_error_prefix("context2");
	teel_set_error_prefix("context3");
	EXPECT_STREQ(teel_get_error(), "context3: context2: context1: base");
}

TEST(Error, PrefixMaxLen) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");

	teel_set_error("hello");

	char prefix[16384] = {};
	memset(prefix, 'X', 4000);
	teel_set_error_prefix(prefix);

	EXPECT_STREQ(teel_get_error(), ": hello");
}

TEST(Error, Basic) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");
	teel_set_error("expected y at offset %d", 10);
	EXPECT_STREQ(teel_get_error(), "expected y at offset 10");
	teel_clear_error();
	EXPECT_STREQ(teel_get_error(), "");
}

TEST(Error, Prefix) {
	teel_set_error("");
	EXPECT_STREQ(teel_get_error(), "");
	teel_set_error("parser failed on 0xff");
	EXPECT_STREQ(teel_get_error(), "parser failed on 0xff");
	teel_set_error_prefix("failed to decode packet");
	EXPECT_STREQ(teel_get_error(), "failed to decode packet: parser failed on 0xff");
}
